// Rich learning content for kids day pages.
// Keyed by date (YYYY-MM-DD).
//
// Schema for each day:
//   intro: string — 1-2 sentence opener under the hero
//   learn: Article[] — background-knowledge articles ("קצת רקע")
//   attractions: ExtendedAttraction[] — full ride detail
//   shows: ExtendedShow[] — full show detail
//   activities: Activity[] — interactive games specific to this day
//
// Article: { id, icon, title, sub, image?, sections: [{ h?, p }] }
//   - "p" supports inline highlights via {{stat:value}} markup
//
// ExtendedAttraction: { id, name, image, area, intro, min_height_cm?, duration_min?, year?, badges?,
//                       how_it_works?, why_works?, history?, tips?, sub? }
//
// ExtendedShow: { id, name, image, intro, times, duration_min?, history?, tips? }
//
// Activity: { id, type, icon, title, sub, ...payload }
//   types: 'quiz' | 'match' | 'rank'
//
// IMPORTANT: All quiz answer options, match-game right-side items, and rank-game items
// MUST be in Hebrew (numbers and proper-name English are OK, but no English phrases as
// answer choices since target users are Hebrew-only readers age 8-10).

