          { h: 'הצבעים', p: 'המדרגות לא רק לבנות — יש שם {{stat:כתומים, ירוקים, צהובים}}. הצבעים האלה מ{{stat:חיידקים מיוחדים}} שאוהבים לחיות במים חמים. כל סוג של חיידק יוצר צבע אחר. זה אחד המקומות הנדירים בעולם שבהם רואים את החיידקים האלה.' }
