        sections: [
          { p: 'בברייס יש {{stat:7,500 הודוס}} — יותר מכל מקום בעולם. הודו הוא עמוד אבן צר וגבוה שעומד בודד. בברייס הם {{stat:כתומים-אדומים}}, בגלל מינרל הברזל שבסלע.' },
          { h: 'איך הם נוצרים?', p: 'הסיפור התחיל לפני {{stat:60 מיליון שנה}}, כשבמקום הזה היה אגם ענק. סלעי הגיר התרבדו על הקרקעית. כשהאגם התייבש, הסלע נשאר. אז התחיל התהליך הארוך — {{stat:מים חודרים לסדקים}} בסלע, קופאים בחורף, מתרחבים ומפיצים את הסלע. תוך מיליוני שנים, חלקים נופלים — והנשארים הם הודוס.' },
          { h: 'מהר מאוד נשחקים', p: 'הסלע בברייס {{stat:רך}}. הוא נשחק במהירות יחסית — {{stat:60 ס״מ כל מאה שנה}}. כלומר ההודוס בעוד 1,000 שנה ייראו שונה. בעוד 100,000 שנה — הם ייעלמו לחלוטין. אנחנו רואים אותם רגע בחיי הסלע.' }
        ]
